src='''def transform(grid):
    from collections import defaultdict
    h, w = len(grid), len(grid[0])
    colmap = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                colmap.setdefault(c - r, set()).add(v)
    def ok(p):
        m = {}
        for k in colmap:
            res = k % p
            for v in colmap[k]:
                if res in m and m[res] != v:
                    return None
                m[res] = v
        return m
    p = 1
    while True:
        m = ok(p)
        if m:
            break
        p += 1
    return [[m[(c - r) % p] for c in range(w)] for r in range(h)]
'''
